const aria2=(()=>{let hash=Date.now().toString(36)+"-"+Math.random().toString(36).substring(2);let index=0;let events={};let options=new Set(["retries","timeout"]);let pending=new Map;let port=new Promise(async(resolve,reject)=>{if(typeof window!=="undefined"&&typeof SharedWorker!=="undefined"){let worker=new SharedWorker("/aria2-socket-worker.js",{name:"aria2-socket-worker"});let port=worker.port;port.start();window.addEventListener("pagehide",()=>{aria2.unsubscribe()});resolve(port);return}if(typeof chrome!=="undefined"&&chrome.offscreen!=="undefined"){let offscreen=chrome.runtime.getURL("/offscreen.html");chrome.runtime.onConnect.addListener(port=>{if(port.name==="offscreen"){resolve(port)}});chrome.offscreen.createDocument({url:offscreen,reasons:["WORKERS"],justification:"Host of SharedWorker"}).catch(reject);return}reject(new Error("Unsupported runtime environment"))});let message=port.then(port=>{port.onmessage=event=>{let data=event.data;let id=data.id;let func=pending.get(id);if(func){pending.delete(id);func(data.result);return}let post=events[data.type];if(post){post(data.details);return}};return function(type,payload){let id=hash+"-"+index+++"-"+type;return new Promise(resolve=>{pending.set(id,resolve);port.postMessage({id:id,type:type,payload:payload})})}});async function broadcast(type,payload){broadcast=await message;return broadcast(type,payload)}let aria2={call(method,params){return broadcast("call",{method:method,params:params})},multicall(requests){return broadcast("multicall",requests)},connect(jsonrpc,secret){return broadcast("connect",{jsonrpc:jsonrpc,secret:secret})},disconnect(){return broadcast("disconnect")},subscribe(){return broadcast("subscribe")},unsubscribe(){return broadcast("unsubscribe")},set(key,value){return broadcast(key,value)},get(key){return broadcast(key)}};Object.defineProperty(aria2,"onopen",{get(){return events["ws:open"]},set(callback){if(typeof callback==="function"){events["ws:open"]=callback}else{events["ws:open"]=null}}});Object.defineProperty(aria2,"onclose",{get(){return events["ws:close"]},set(callback){if(typeof callback==="function"){events["ws:close"]=callback}else{events["ws:close"]=null}}});Object.defineProperty(aria2,"onmessage",{get(){return events["ws:message"]},set(callback){if(typeof callback==="function"){events["ws:message"]=callback}else{events["ws:message"]=null}}});return aria2})();